<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class CommitteeMinute extends Model{protected $fillable=['meeting_id','minute_number','status','version','document_path','document_hash','documento_id','generated_by','generated_at','approved_by','approved_at','finalized_by','finalized_at','observations'];protected $casts=['generated_at'=>'datetime','approved_at'=>'datetime','finalized_at'=>'datetime'];public function meeting(){return $this->belongsTo(CommitteeMeeting::class);}public function document(){return $this->belongsTo(Documento::class,'documento_id');}}
